-- =============================================
-- 89. 기출 문제 은행 — 문학 지문에 잘못 붙은 문항 떼기 2차 (데이터 교정)
-- 실행: node /Users/ara/Projects/Ara-system/scripts/run-sql.js sql/89_problem_bank_detach_glued_round2.sql
-- =============================================
-- sql/86 은 문법 낱말이 든 문항을 보았다. 이 파일은 **그 밖의 문학 지문 문항** 가운데 지문을 가리키는 말이 없는 것을 읽어
-- 정한 값이다(detach-audit-2026-11-06/r2). 뗀 것은 셋이다: 문법 문항 · 대화의 원리·협상·매체처럼 작품과 무관한 화법·작문 문항 ·
-- 다른 작품을 제 상자에 실어 묻는 문항.
--
-- ⚠️ '위와 같은 글의 특징'·'시조에 대한 설명' 처럼 **그 지문의 갈래를 묻는 문항은 남겼다.** 코덱스는 이것까지 뗀다고 했지만
--    그 시험에서 그 지문을 두고 낸 문항이고, 작품 문제지에 함께 있어도 자연스럽다. 총괄이 170건을 읽어 갈랐다.
-- ⚠️ 뗀다는 것의 뜻과 조건·멱등·감사 로그·스펙 규약은 sql/86 머리말과 같다. 사람이 정한 값이라 재계산할 수 없다.

BEGIN;

SET LOCAL search_path = exam, public;

CREATE TEMP TABLE _detach (
  id         UUID PRIMARY KEY,
  passage_id UUID NOT NULL,
  stem_md5   TEXT NOT NULL,
  area       TEXT[],
  clear_unit BOOLEAN NOT NULL,
  note       TEXT NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE _labels (
  passage_id UUID PRIMARY KEY,
  old_label  TEXT NOT NULL,
  new_label  TEXT NOT NULL
) ON COMMIT DROP;



DO $detach$
DECLARE
  v_total    INT;
  v_done     INT;
  v_already  INT;
  v_changed  INT;
  v_labels   INT;
  v_bad      INT;
  r          RECORD;
BEGIN
  IF to_regclass('exam.problems') IS NULL THEN
    RAISE EXCEPTION 'exam.problems 가 없습니다 (현재 DB: %).', current_database();
  END IF;
  RAISE NOTICE '대상 DB=% / 롤=%', current_database(), current_user;

  SELECT count(*) INTO v_total FROM _detach;
  SELECT count(*) INTO v_already FROM _detach d JOIN exam.problems p ON p.id = d.id WHERE p.passage_id IS NULL;

  UPDATE exam.problems p
     SET passage_id  = NULL,
         work_titles = '{}',
         area_path   = COALESCE(d.area, p.area_path),
         unit_path   = CASE WHEN d.clear_unit THEN '{}'::text[] ELSE p.unit_path END
    FROM _detach d
   WHERE p.id = d.id AND p.passage_id = d.passage_id AND md5(p.stem_html) = d.stem_md5;
  GET DIAGNOSTICS v_done = ROW_COUNT;

  v_changed := v_total - v_done - v_already;
  RAISE NOTICE '뗀 문항 % / 이미 뗌 % / 그 사이 바뀌어 건너뜀 % (목록 %)', v_done, v_already, v_changed, v_total;
  FOR r IN
    SELECT d.note FROM _detach d JOIN exam.problems p ON p.id = d.id
     WHERE p.passage_id IS NOT NULL
  LOOP
    RAISE NOTICE '건너뜀: %', r.note;
  END LOOP;

  UPDATE exam.passages ps SET label = l.new_label
    FROM _labels l WHERE ps.id = l.passage_id AND ps.label = l.old_label;
  GET DIAGNOSTICS v_labels = ROW_COUNT;
  RAISE NOTICE '지문 머리 고침 %', v_labels;

  -- 검증 — 뗀 문항이 어느 트리거에도 되살아나지 않았는가
  SELECT count(*) INTO v_bad FROM _detach d JOIN exam.problems p ON p.id = d.id
   WHERE p.passage_id IS NULL AND (cardinality(p.work_titles) > 0 OR p.work_title <> '' OR p.passage_area <> '');
  IF v_bad > 0 THEN RAISE EXCEPTION '뗀 문항 %건에 작품·지문 영역이 남았습니다.', v_bad; END IF;

  -- 검증 — 문항이 하나도 안 남은 지문이 새로 생기지 않았는가(지문만 덩그러니 남으면 안 된다)
  SELECT count(DISTINCT d.passage_id) INTO v_bad FROM _detach d
   WHERE NOT EXISTS (SELECT 1 FROM exam.problems q WHERE q.passage_id = d.passage_id);
  IF v_bad > 0 THEN RAISE EXCEPTION '문항이 안 남은 지문이 %건 생겼습니다.', v_bad; END IF;

  SELECT count(*) INTO v_bad FROM exam.work_title_suspects();
  IF v_bad > 0 THEN RAISE EXCEPTION '닮은 작품명 %쌍 — exam.work_title_suspects() 를 보세요.', v_bad; END IF;
END
$detach$;

SELECT exam.archive_facets_refresh();

COMMIT;
